sys_script.script:
(function executeRule(current, previous) {
    try {
        if (!gs.hasRole('x_848842_techdesk.admin')) {
            if (current.request_type.changes() || current.requested_by.changes() || current.cost_estimate.changes()) {
                current.setAbortAction(true);
                gs.addErrorMessage('Cannot modify request_type, requested_by, or cost_estimate after approval');
            }
        }
    } catch (e) {
        gs.error('TechDesk: Error in block-edit-after-approval - ' + e.message);
    }
})(current, previous);
